import{_ as a,c as n,d as l,Z as e}from"./chunks/framework.B0uuYL3Y.js";const p="/microarch/smt-issue-slots.png",b=JSON.parse('{"title":"同核多线程怎样安排任务","description":"从两个逻辑 CPU 共用执行资源讲起，用 Linux 的核心调度推算任务配对和强制空闲。","frontmatter":{"title":"同核多线程怎样安排任务","description":"从两个逻辑 CPU 共用执行资源讲起，用 Linux 的核心调度推算任务配对和强制空闲。","date":"2026-11-26","tags":["微架构安全","SMT","Linux","核心调度","资源隔离"],"book":"microarch-00-intro"},"headers":[],"relativePath":"posts/microarch-06d-core-scheduling.md","filePath":"posts/microarch-06d-core-scheduling.md"}'),o={name:"posts/microarch-06d-core-scheduling.md"};function t(r,s,c,i,d,y){return n(),l("div",null,s[0]||(s[0]=[e('<p>一个物理核心有两个逻辑 CPU。某一侧明明有可运行的任务，Linux 却让它空闲。这可能是核心调度作出的决定。要理解这个决定，先看两个逻辑 CPU 在硬件里共用什么，再沿内核的两个运行队列算一次任务选择。</p><nav class="table-of-contents"><ul><li><a href="#smt-resources">两个逻辑 CPU 共用哪些资源</a></li><li><a href="#core-cookie">内核用什么表示哪些任务可以同核</a></li><li><a href="#core-pick">算一次跨两个运行队列的选择</a><ul><li><a href="#用程序检查配对和空闲记账">用程序检查配对和空闲记账</a></li></ul></li><li><a href="#core-boundary">这项调度挡住的是哪一种共享</a></li><li><a href="#参考文献">参考文献</a></li></ul></nav><h2 id="smt-resources" tabindex="-1">两个逻辑 CPU 共用哪些资源 <a class="header-anchor" href="#smt-resources" aria-label="Permalink to &quot;两个逻辑 CPU 共用哪些资源 {#smt-resources}&quot;">​</a></h2><p><strong>同时多线程</strong>（Simultaneous Multithreading，SMT）让一个物理核心容纳多个硬件线程。在支持 Intel Hyper-Threading 的核心上，操作系统可以把两个硬件线程视为两个逻辑 CPU。各自有独立的架构寄存器和控制状态，因此可以执行两条独立指令流。它们还会使用同一核心内的部分资源，例如执行单元、缓存和互连。具体哪些队列共享、分区或按线程分开，要看处理器实现。</p><table tabindex="0"><thead><tr><th>要读的状态</th><th>在同核两个线程中怎样组织</th></tr></thead><tbody><tr><td>架构状态</td><td>寄存器等状态分别对应各自的逻辑 CPU</td></tr><tr><td>执行资源</td><td>指令来自不同硬件线程，可以竞争同一核心里的可用执行槽</td></tr><tr><td>缓存与传输</td><td>有些级别及通路是共用的，具体共享范围要由拓扑和型号确定</td></tr><tr><td>软件运行队列</td><td>Linux 分别为逻辑 CPU 管理待运行任务。核心调度可以联合查看同一核心的队列</td></tr></tbody></table><p>下面的原图把共享的执行槽画得很清楚。每列是一拍，每列两个方格代表同一核心在该拍可用的两个槽。深灰与浅灰方格分别由两个任务使用，× 表示没用上的槽。中间一幅启用了 SMT，某些列同时出现深、浅两种颜色。这说明两条指令流在同一拍使用了共用资源。图的下半部分还给出任务开始时间改变后的分配。</p><figure class="lesson-figure" style="max-width:520px;"><a href="/microarch/smt-issue-slots.png" aria-label="放大查看 SMT 执行槽原图"><img src="'+p+`" alt="同一个两槽核心的三种执行示意，深灰和浅灰分别为两个任务，叉号表示空槽，其中启用 SMT 的图在同一周期安排了两个任务" width="520" height="407" loading="lazy" decoding="async"></a><figcaption>图 1　两个任务的执行槽使用示意。上方是顺序执行，中间是同时运行，下方改变了同时运行的开始时刻。</figcaption></figure><p>当一个线程暂时没有足够的就绪指令，另一个线程可能利用剩余资源。反过来，两者若同时需要同一资源，也可能互相拖慢。要判断是否存在这种直接的同核争用，先确认拓扑。Linux 的 <code>core_cpus_list</code> 文件列出与指定 CPU 同属一个物理核心的逻辑 CPU。例如下列只读命令在本节题设机器上返回 <code>0,4</code>。</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#268BD2;">cat</span><span style="color:#2AA198;"> /sys/devices/system/cpu/cpu0/topology/core_cpus_list</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这个例子里，CPU 0 与 CPU 4 是同核线程。另两颗逻辑 CPU 即使<a href="./microarch-06a-shared-cache.html#llc-domain">共用同一个末级缓存</a>，也可能属于不同核心。判断缓存共享要查缓存域，判断同核执行要查核心拓扑。</p><h2 id="core-cookie" tabindex="-1">内核用什么表示哪些任务可以同核 <a class="header-anchor" href="#core-cookie" aria-label="Permalink to &quot;内核用什么表示哪些任务可以同核 {#core-cookie}&quot;">​</a></h2><p>Linux 的<strong>核心调度</strong>（core scheduling）在选任务时考虑 SMT 同核关系。<code>CONFIG_SCHED_CORE</code> 提供这项功能。启用并按信任关系编组后，调度器将同一 cookie 的任务视为可以一起使用一个核心。这里的 cookie 是内核用于比较的任务标签。</p><table tabindex="0"><thead><tr><th>调度状态</th><th>保存和使用的内容</th></tr></thead><tbody><tr><td>任务的 <code>core_cookie</code></td><td>任务所在组的标签。相同值表示可以配对</td></tr><tr><td>每个逻辑 CPU 的运行队列</td><td>能在该逻辑 CPU 上候选的任务。需要时也能查找指定标签的任务</td></tr><tr><td>核心级的 <code>core_cookie</code></td><td>本轮由全核心最优先候选任务选定的标签</td></tr><tr><td>每个逻辑 CPU 的 <code>core_pick</code></td><td>本轮为该逻辑 CPU 选定的任务，可以是空闲任务</td></tr><tr><td><code>core_forceidle_count</code></td><td>本轮有就绪任务、但仍选中空闲任务的逻辑 CPU 数量</td></tr></tbody></table><p>系统启动时，任务默认 cookie 为 0。默认组中的任务彼此可配对。用户空间可以通过 <code>PR_SCHED_CORE</code> 接口查询、创建或按权限共享标签。新建的标签与默认组不同。拥有新标签的任务同核运行时仍要检查另一侧的标签。空闲任务在配对时作特殊处理，允许和任何组搭配。普通任务的 cookie 0 与这个特殊空闲规则含义不同。</p><h2 id="core-pick" tabindex="-1">算一次跨两个运行队列的选择 <a class="header-anchor" href="#core-pick" aria-label="Permalink to &quot;算一次跨两个运行队列的选择 {#core-pick}&quot;">​</a></h2><p>看 CPU 0 和 CPU 4 的题设。A0、A1 属于同一组，cookie 为 α。B0、B1 属于另一组，cookie 为 β。以下排名是题设已经给出的调度顺序，数字越大越优先。Linux 实际还会考虑调度类及其状态，这里直接从给定候选开始。</p><table tabindex="0"><thead><tr><th>任务</th><th>cookie</th><th style="text-align:right;">调度排名</th></tr></thead><tbody><tr><td>A0</td><td>α</td><td style="text-align:right;">90</td></tr><tr><td>A1</td><td>α</td><td style="text-align:right;">60</td></tr><tr><td>B0</td><td>β</td><td style="text-align:right;">80</td></tr><tr><td>B1</td><td>β</td><td style="text-align:right;">50</td></tr></tbody></table><p>在 Linux v6.12 的核心联合选择路径中，先分别从两个运行队列选出本地优先任务，再从它们中确定全核心最优先的候选。它的 cookie 成为本轮约束。各逻辑 CPU 的本地首选若与本轮 cookie 匹配，就直接采用。否则再尝试从本地找相容任务。如果队列非空却找不到可配对的任务，最终选择空闲，这就叫<strong>强制空闲</strong>。</p><table tabindex="0"><thead><tr><th>时间区间</th><th>CPU 0 就绪</th><th>CPU 4 就绪</th><th>实际配对</th><th>哪一侧空闲</th></tr></thead><tbody><tr><td>0–2 ms</td><td>A0</td><td>B0、A1</td><td>A0 与 A1</td><td>无</td></tr><tr><td>2–5 ms</td><td>A0</td><td>B0</td><td>A0 与空闲</td><td>CPU 4 强制空闲</td></tr><tr><td>5–7 ms</td><td>B1</td><td>B0</td><td>B1 与 B0</td><td>无</td></tr><tr><td>7–8 ms</td><td>无</td><td>B0</td><td>空闲与 B0</td><td>CPU 0 自然空闲</td></tr></tbody></table><p>第一段，两个本地首选是 A0 和 B0。全核心最优先的是 A0，所以 CPU 4 放下本地首选 B0，改用较低排名的 A1。第二段 A1 已经阻塞，CPU 4 明明还有 B0 可运行，却缺少能和 A0 搭配的任务。第三段换成 B0 决定本轮的 cookie，B1 正好能配对。最后一段 CPU 0 的队列已经空了，即使去掉配对约束，它也仍然会空闲。</p><p>在这 8 毫秒里，两个逻辑 CPU 合计提供 16 个逻辑 CPU·毫秒。其中 3 个属于强制空闲，1 个属于自然空闲，剩余 12 个在运行题设任务。这个加法统计的是调度时间。具体能执行多少指令，还取决于核心内的资源分配和两项工作的相互影响。</p><h3 id="用程序检查配对和空闲记账" tabindex="-1">用程序检查配对和空闲记账 <a class="header-anchor" href="#用程序检查配对和空闲记账" aria-label="Permalink to &quot;用程序检查配对和空闲记账&quot;">​</a></h3><p>以下是同一张表的 Python 3 模型。每行输入描述一个区间内固定的两份就绪队列。程序先选全核心 cookie，再对每条队列取排名最高的匹配项。队列里有任务却选不出匹配项时，才给该逻辑 CPU 记强制空闲。</p><div class="language-python line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#586E75;font-style:italic;"># 元组依次记录任务名、cookie 和排名。</span></span>
<span class="line"><span style="color:#839496;">a0 </span><span style="color:#859900;">=</span><span style="color:#839496;"> (</span><span style="color:#2AA198;">&quot;A0&quot;</span><span style="color:#839496;">, </span><span style="color:#2AA198;">&quot;alpha&quot;</span><span style="color:#839496;">, </span><span style="color:#D33682;">90</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#839496;">a1 </span><span style="color:#859900;">=</span><span style="color:#839496;"> (</span><span style="color:#2AA198;">&quot;A1&quot;</span><span style="color:#839496;">, </span><span style="color:#2AA198;">&quot;alpha&quot;</span><span style="color:#839496;">, </span><span style="color:#D33682;">60</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#839496;">b0 </span><span style="color:#859900;">=</span><span style="color:#839496;"> (</span><span style="color:#2AA198;">&quot;B0&quot;</span><span style="color:#839496;">, </span><span style="color:#2AA198;">&quot;beta&quot;</span><span style="color:#839496;">, </span><span style="color:#D33682;">80</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#839496;">b1 </span><span style="color:#859900;">=</span><span style="color:#839496;"> (</span><span style="color:#2AA198;">&quot;B1&quot;</span><span style="color:#839496;">, </span><span style="color:#2AA198;">&quot;beta&quot;</span><span style="color:#839496;">, </span><span style="color:#D33682;">50</span><span style="color:#839496;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#839496;">windows </span><span style="color:#859900;">=</span><span style="color:#839496;"> [</span></span>
<span class="line"><span style="color:#839496;">    (</span><span style="color:#D33682;">0</span><span style="color:#839496;">, </span><span style="color:#D33682;">2</span><span style="color:#839496;">, ([a0], [b0, a1])),</span></span>
<span class="line"><span style="color:#839496;">    (</span><span style="color:#D33682;">2</span><span style="color:#839496;">, </span><span style="color:#D33682;">5</span><span style="color:#839496;">, ([a0], [b0])),</span></span>
<span class="line"><span style="color:#839496;">    (</span><span style="color:#D33682;">5</span><span style="color:#839496;">, </span><span style="color:#D33682;">7</span><span style="color:#839496;">, ([b1], [b0])),</span></span>
<span class="line"><span style="color:#839496;">    (</span><span style="color:#D33682;">7</span><span style="color:#839496;">, </span><span style="color:#D33682;">8</span><span style="color:#839496;">, ([], [b0])),</span></span>
<span class="line"><span style="color:#839496;">]</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">def</span><span style="color:#268BD2;"> rank</span><span style="color:#839496;">(task):</span></span>
<span class="line"><span style="color:#859900;">    return</span><span style="color:#839496;"> task[</span><span style="color:#D33682;">2</span><span style="color:#839496;">]</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span style="color:#93A1A1;font-weight:bold;">def</span><span style="color:#268BD2;"> core_pick</span><span style="color:#839496;">(queues):</span></span>
<span class="line"><span style="color:#839496;">    candidates </span><span style="color:#859900;">=</span><span style="color:#839496;"> [</span><span style="color:#268BD2;">max</span><span style="color:#839496;">(queue, key</span><span style="color:#859900;">=</span><span style="color:#839496;">rank) </span><span style="color:#859900;">for</span><span style="color:#839496;"> queue </span><span style="color:#859900;">in</span><span style="color:#839496;"> queues </span><span style="color:#859900;">if</span><span style="color:#839496;"> queue]</span></span>
<span class="line"><span style="color:#859900;">    if</span><span style="color:#859900;"> not</span><span style="color:#839496;"> candidates:</span></span>
<span class="line"><span style="color:#859900;">        return</span><span style="color:#839496;"> [</span><span style="color:#B58900;">None</span><span style="color:#839496;">] </span><span style="color:#859900;">*</span><span style="color:#268BD2;"> len</span><span style="color:#839496;">(queues), </span><span style="color:#D33682;">0</span></span>
<span class="line"></span>
<span class="line"><span style="color:#839496;">    _, cookie, _ </span><span style="color:#859900;">=</span><span style="color:#268BD2;"> max</span><span style="color:#839496;">(candidates, key</span><span style="color:#859900;">=</span><span style="color:#839496;">rank)</span></span>
<span class="line"><span style="color:#839496;">    picks </span><span style="color:#859900;">=</span><span style="color:#839496;"> []</span></span>
<span class="line"><span style="color:#839496;">    forced </span><span style="color:#859900;">=</span><span style="color:#D33682;"> 0</span></span>
<span class="line"><span style="color:#859900;">    for</span><span style="color:#839496;"> queue </span><span style="color:#859900;">in</span><span style="color:#839496;"> queues:</span></span>
<span class="line"><span style="color:#839496;">        matching </span><span style="color:#859900;">=</span><span style="color:#839496;"> [task </span><span style="color:#859900;">for</span><span style="color:#839496;"> task </span><span style="color:#859900;">in</span><span style="color:#839496;"> queue </span><span style="color:#859900;">if</span><span style="color:#839496;"> task[</span><span style="color:#D33682;">1</span><span style="color:#839496;">] </span><span style="color:#859900;">==</span><span style="color:#839496;"> cookie]</span></span>
<span class="line"><span style="color:#839496;">        winner </span><span style="color:#859900;">=</span><span style="color:#268BD2;"> max</span><span style="color:#839496;">(matching, key</span><span style="color:#859900;">=</span><span style="color:#839496;">rank, default</span><span style="color:#859900;">=</span><span style="color:#B58900;">None</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#839496;">        picks.append(winner[</span><span style="color:#D33682;">0</span><span style="color:#839496;">] </span><span style="color:#859900;">if</span><span style="color:#839496;"> winner </span><span style="color:#859900;">else</span><span style="color:#B58900;"> None</span><span style="color:#839496;">)</span></span>
<span class="line"><span style="color:#859900;">        if</span><span style="color:#839496;"> winner </span><span style="color:#859900;">is</span><span style="color:#B58900;"> None</span><span style="color:#859900;"> and</span><span style="color:#839496;"> queue:</span></span>
<span class="line"><span style="color:#839496;">            forced </span><span style="color:#859900;">+=</span><span style="color:#D33682;"> 1</span></span>
<span class="line"><span style="color:#859900;">    return</span><span style="color:#839496;"> picks, forced</span></span>
<span class="line"></span>
<span class="line"></span>
<span class="line"><span style="color:#839496;">forced_time </span><span style="color:#859900;">=</span><span style="color:#D33682;"> 0</span></span>
<span class="line"><span style="color:#839496;">actual_picks </span><span style="color:#859900;">=</span><span style="color:#839496;"> []</span></span>
<span class="line"><span style="color:#859900;">for</span><span style="color:#839496;"> start, end, queues </span><span style="color:#859900;">in</span><span style="color:#839496;"> windows:</span></span>
<span class="line"><span style="color:#839496;">    picked, forced </span><span style="color:#859900;">=</span><span style="color:#839496;"> core_pick(queues)</span></span>
<span class="line"><span style="color:#839496;">    actual_picks.append(picked)</span></span>
<span class="line"><span style="color:#839496;">    forced_time </span><span style="color:#859900;">+=</span><span style="color:#839496;"> (end </span><span style="color:#859900;">-</span><span style="color:#839496;"> start) </span><span style="color:#859900;">*</span><span style="color:#839496;"> forced</span></span>
<span class="line"></span>
<span class="line"><span style="color:#859900;">assert</span><span style="color:#839496;"> actual_picks </span><span style="color:#859900;">==</span><span style="color:#839496;"> [[</span><span style="color:#2AA198;">&quot;A0&quot;</span><span style="color:#839496;">, </span><span style="color:#2AA198;">&quot;A1&quot;</span><span style="color:#839496;">], [</span><span style="color:#2AA198;">&quot;A0&quot;</span><span style="color:#839496;">, </span><span style="color:#B58900;">None</span><span style="color:#839496;">], [</span><span style="color:#2AA198;">&quot;B1&quot;</span><span style="color:#839496;">, </span><span style="color:#2AA198;">&quot;B0&quot;</span><span style="color:#839496;">], [</span><span style="color:#B58900;">None</span><span style="color:#839496;">, </span><span style="color:#2AA198;">&quot;B0&quot;</span><span style="color:#839496;">]]</span></span>
<span class="line"><span style="color:#859900;">assert</span><span style="color:#839496;"> forced_time </span><span style="color:#859900;">==</span><span style="color:#D33682;"> 3</span></span>
<span class="line"><span style="color:#268BD2;">print</span><span style="color:#839496;">(</span><span style="color:#2AA198;">&quot;picks:&quot;</span><span style="color:#839496;">, actual_picks)</span></span>
<span class="line"><span style="color:#268BD2;">print</span><span style="color:#839496;">(</span><span style="color:#2AA198;">&quot;forced idle, logical CPU-ms:&quot;</span><span style="color:#839496;">, forced_time)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br><span class="line-number">44</span><br><span class="line-number">45</span><br><span class="line-number">46</span><br></div></div><h2 id="core-boundary" tabindex="-1">这项调度挡住的是哪一种共享 <a class="header-anchor" href="#core-boundary" aria-label="Permalink to &quot;这项调度挡住的是哪一种共享 {#core-boundary}&quot;">​</a></h2><p>核心调度直接改变的是任务的<strong>同核并行关系</strong>。一次切换后，各逻辑 CPU 还要落实本轮的选择。Linux 可能通过核间中断通知同核另一侧重新调度。文档也讨论了通知处理延迟、内核替某个任务执行代码等情况下的限度。这里的 Python 模型只模拟选谁，真实运行要结合硬件和内核的保护保证来读。</p><p>如果两个任务在同一逻辑 CPU 上先后运行，还需要分析先前状态能否影响下一段执行。比如<a href="./microarch-04c-variants.html#variant-switch">间接分支预测屏障</a>对应执行顺序中的前后两段。如果它们位于不同核心但共用 LLC，仍需考虑<a href="./microarch-06c-cat.html#cat-ways">组内替换和分配范围</a>。区分这三种情形，可以先写下两个任务的物理位置和时间关系，再找对应的控制。</p><details class="details custom-block"><summary>练习：A1 在第一段开始前就已阻塞</summary><p>将第一段 CPU 4 的队列改为只有 B0，其他区间全部保持原样。前 2 毫秒谁会运行？四段合起来的强制空闲时间是多少？</p><p>A0 的排名仍高于 B0，第一段继续由 α 决定配对。CPU 4 找不到同组任务，新增 2 个逻辑 CPU·毫秒的强制空闲。之后三段不变，合计由 3 增到 5。B0 的排名和可运行状态都没有变，变化的是可用的同组搭档。</p></details><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li><a href="https://edc.intel.com/content/www/us/en/design/products/platforms/details/alder-lake-desktop/12th-generation-intel-core-processors-datasheet-volume-1-of-2/intel-hyper-threading-technology/" target="_blank" rel="noreferrer">Intel 第 12 代 Core 处理器数据手册，Hyper-Threading 的架构状态与共享资源</a></li><li><a href="https://drops.dagstuhl.de/entities/document/10.4230/LIPIcs.ECRTS.2020.14" target="_blank" rel="noreferrer">Sims Hill Osborne、James H. Anderson，Simultaneous Multithreading and Hard Real Time: Can It Be Safe?，图 2</a> · <a href="https://creativecommons.org/licenses/by/3.0/" target="_blank" rel="noreferrer">CC BY 3.0 许可</a> · 本文裁出原图和图例。</li><li><a href="https://docs.kernel.org/6.12/admin-guide/hw-vuln/core-scheduling.html" target="_blank" rel="noreferrer">Linux v6.12 核心调度文档，cookie、任务挑选与强制空闲</a></li><li><a href="https://github.com/torvalds/linux/blob/v6.12/kernel/sched/core.c#L6146" target="_blank" rel="noreferrer">Linux v6.12 调度源码，两个逻辑 CPU 的联合选择</a></li><li><a href="https://github.com/torvalds/linux/blob/v6.12/Documentation/ABI/testing/sysfs-devices-system-cpu" target="_blank" rel="noreferrer">Linux 的 CPU 拓扑接口定义</a></li></ul><nav class="article-nav" aria-label="系列文章导航"><p><a href="./microarch-06c-cat.html" class="article-nav-card article-nav-prev" rel="prev"><span class="article-nav-text"><small>上一篇</small><strong>划分末级缓存的路能隔离什么</strong></span></a></p><p><a href="./microarch-04d-spectre-v1.html" class="article-nav-card article-nav-next" rel="next"><span class="article-nav-text"><small>下一篇</small><strong>Spectre v1 中的边界检查为何会被越过</strong></span></a></p></nav>`,31)]))}const h=a(o,[["render",t]]);export{b as __pageData,h as default};
